package com.college.notes.controller;
import com.college.notes.entity.*; import com.college.notes.repository.*; import com.college.notes.service.CurrentUser; import org.springframework.web.bind.annotation.*; import java.time.LocalDateTime; import java.util.*;
@RestController @RequestMapping("/api/requests") public class RequestController {private final AccessRequestRepository repo;private final UserRepository users;private final SubjectRepository subjects;private final CurrentUser current;public RequestController(AccessRequestRepository r,UserRepository u,SubjectRepository s,CurrentUser c){repo=r;users=u;subjects=s;current=c;} @GetMapping public List<AccessRequest> list(){User u=current.get();return u.getRole()==Role.FACULTY?repo.findByFacultyIdOrderByRequestDateDesc(u.getId()):repo.findByStudentIdOrderByRequestDateDesc(u.getId());} @PostMapping public AccessRequest create(@RequestBody Map<String,Long> body){User student=current.get();if(student.getRole()!=Role.STUDENT)throw new IllegalArgumentException("Students only");Long facultyId=body.get("facultyId"),subjectId=body.get("subjectId");Subject s=subjects.findById(subjectId).orElseThrow();if(!s.getFaculty().getId().equals(facultyId))throw new IllegalArgumentException("Subject does not belong to faculty");var existing=repo.findByStudentIdAndFacultyIdAndSubjectId(student.getId(),facultyId,subjectId);if(existing.isPresent()){existing.get().setStatus(RequestStatus.PENDING);existing.get().setRequestDate(LocalDateTime.now());existing.get().setResponseDate(null);return repo.save(existing.get());}AccessRequest r=new AccessRequest();r.setStudent(student);r.setFaculty(users.findById(facultyId).orElseThrow());r.setSubject(s);r.setStatus(RequestStatus.PENDING);return repo.save(r);} @PutMapping("/{id}") public AccessRequest decide(@PathVariable Long id,@RequestParam RequestStatus status){User f=current.get();if(f.getRole()!=Role.FACULTY)throw new IllegalArgumentException("Faculty only");AccessRequest r=repo.findById(id).orElseThrow();if(!r.getFaculty().getId().equals(f.getId()))throw new IllegalArgumentException("Not your request");if(status==RequestStatus.PENDING)throw new IllegalArgumentException("Invalid status");r.setStatus(status);r.setResponseDate(LocalDateTime.now());return repo.save(r);} }
